{'role': 'user', 'content': [{'tool_use_id': 'toolu_014gsACvh95MirhqdyWrS7AH', 'type': 'tool_result', 'content': '     1→/** API functions and hooks for scan & batch analyze flow (FE-4). */
     2→
     3→import { useQuery } from "@tanstack/react-query";
     4→import { apiFetch } from "./client";
     5→import type { ScanResponse, BatchAnalyzeResponse, JobStatus, BrowseResponse } from "../types";
     6→
     7→export async function scanDirectory(path: string): Promise<ScanResponse> {
     8→  return apiFetch<ScanResponse>("/tracks/scan", {
     9→    method: "POST",
    10→    body: JSON.stringify({ path }),
    11→  });
    12→}
    13→
    14→export async function startBatchAnalysis(
    15→  paths: string[],
    16→  skipWaveform = false,
    17→): Promise<BatchAnalyzeResponse> {
    18→  return apiFetch<BatchAnalyzeResponse>("/tracks/analyze-batch", {
    19→    method: "POST",
    20→    body: JSON.stringify({ paths, skip_waveform: skipWaveform }),
    21→  });
    22→}
    23→
    24→export async function browseFilesystem(path?: string): Promise<BrowseResponse> {
    25→  const qs = path ? `?path=${encodeURIComponent(path)}` : "";
    26→  return apiFetch<BrowseResponse>(`/filesystem/browse${qs}`, { method: "GET" });
    27→}
    28→
    29→export function useJobStatus(jobId: string | null) {
    30→  return useQuery<JobStatus>({
    31→    queryKey: ["job", jobId],
    32→    queryFn: () => apiFetch<JobStatus>(`/tracks/jobs/${jobId}`),
    33→    enabled: !!jobId,
    34→    refetchInterval: (query) => {
    35→      const status = query.state.data?.status;
    36→      if (status === "complete" || status === "failed") return false;
    37→      return 1000;
    38→    },
    39→  });
    40→}
    41→'}]}

