{'role': 'user', 'content': [{'tool_use_id': 'toolu_01AdwUxxzqA4FfCD5GeLrrZj', 'type': 'tool_result', 'content': '     1→/** TanStack Query hooks for /api/tracks endpoints. */
     2→
     3→import { useQuery } from "@tanstack/react-query";
     4→import { apiFetch } from "./client";
     5→import type { TrackAnalysis, TrackListResponse } from "../types";
